const listDueReservationOrganizations = `-- name: ListDueReservationOrganizations :many
SELECT DISTINCT r.organization_id
FROM reservations r
WHERE (r.status = 'awaiting_review' AND r.review_deadline <= $1::timestamptz)
   OR (r.status = 'awaiting_payment' AND r.payment_deadline <= $1::timestamptz)
LIMIT 1000
`

// Organizations with waiting reservations past their deadline (sweep).
func (q *Queries) ListDueReservationOrganizations(ctx context.Context, nowAt pgtype.Timestamptz) ([]int64, error) {
	rows, err := q.db.Query(ctx, listDueReservationOrganizations, nowAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int64{}
	for rows.Next() {
		var organization_id int64
		if err := rows.Scan(&organization_id); err != nil {
			return nil, err
		}
		items = append(items, organization_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

