const transitionReservation = `-- name: TransitionReservation :execrows
UPDATE reservations
SET status = $1,
    capacity_commitment = $2,
    review_deadline = $3,
    payment_deadline = $4,
    confirmed_at = COALESCE(confirmed_at, $5),
    cancelled_at = COALESCE($6, cancelled_at),
    cancel_reason = CASE WHEN $7::text <> '' THEN $7::text ELSE cancel_reason END,
    allocation_id = COALESCE($8, allocation_id)
WHERE organization_id = $9
  AND id = $10
  AND status = $11
`

type TransitionReservationParams struct {
	ToStatus           string             `json:"to_status"`
	CapacityCommitment string             `json:"capacity_commitment"`
	ReviewDeadline     pgtype.Timestamptz `json:"review_deadline"`
	PaymentDeadline    pgtype.Timestamptz `json:"payment_deadline"`
	ConfirmedAt        pgtype.Timestamptz `json:"confirmed_at"`
	CancelledAt        pgtype.Timestamptz `json:"cancelled_at"`
	CancelReason       string             `json:"cancel_reason"`
	AllocationID       pgtype.Int8        `json:"allocation_id"`
	OrganizationID     int64              `json:"organization_id"`
	ID                 int64              `json:"id"`
	FromStatus         string             `json:"from_status"`
}

// Moves the status (optimistic: only from the expected status).
func (q *Queries) TransitionReservation(ctx context.Context, arg TransitionReservationParams) (int64, error) {
	result, err := q.db.Exec(ctx, transitionReservation,
		arg.ToStatus,
		arg.CapacityCommitment,
		arg.ReviewDeadline,
		arg.PaymentDeadline,
		arg.ConfirmedAt,
		arg.CancelledAt,
		arg.CancelReason,
		arg.AllocationID,
		arg.OrganizationID,
		arg.ID,
		arg.FromStatus,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateReservationPlan = `-- name: UpdateReservationPlan :execrows
UPDATE reservations
SET allocation_id = $1,
    starts_at = $2,
    ends_at = $3,
    pickup_branch_id = $4,
    return_branch_id = $5,
    pickup_point_id = $6,
    return_point_id = $7,
    rental_product_id = $8,
    product_version = $9,
    guarantee_type = $10,
    product_snapshot = $11,
    total_amount = $12,
    prepayment_amount = $13,
    net_receivable = $14,
    quote_id = $15,
    quote_snapshot = $16
WHERE organization_id = $17
  AND id = $18
`

type UpdateReservationPlanParams struct {
	AllocationID     pgtype.Int8        `json:"allocation_id"`
	StartsAt         pgtype.Timestamptz `json:"starts_at"`
	EndsAt           pgtype.Timestamptz `json:"ends_at"`
	PickupBranchID   int64              `json:"pickup_branch_id"`
	ReturnBranchID   int64              `json:"return_branch_id"`
	PickupPointID    pgtype.Int8        `json:"pickup_point_id"`
	ReturnPointID    pgtype.Int8        `json:"return_point_id"`
	RentalProductID  int64              `json:"rental_product_id"`
	ProductVersion   int32              `json:"product_version"`
	GuaranteeType    string             `json:"guarantee_type"`
	ProductSnapshot  []byte             `json:"product_snapshot"`
	TotalAmount      pgtype.Numeric     `json:"total_amount"`
	PrepaymentAmount pgtype.Numeric     `json:"prepayment_amount"`
	NetReceivable    pgtype.Numeric     `json:"net_receivable"`
	QuoteID          pgtype.Int8        `json:"quote_id"`
	QuoteSnapshot    []byte             `json:"quote_snapshot"`
	OrganizationID   int64              `json:"organization_id"`
	ID               int64              `json:"id"`
}

// Dates / places / product / price after a change, an extension or an
// upgrade (the sold product columns never change).
func (q *Queries) UpdateReservationPlan(ctx context.Context, arg UpdateReservationPlanParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateReservationPlan,
		arg.AllocationID,
		arg.StartsAt,
		arg.EndsAt,
		arg.PickupBranchID,
		arg.ReturnBranchID,
		arg.PickupPointID,
		arg.ReturnPointID,
		arg.RentalProductID,
		arg.ProductVersion,
		arg.GuaranteeType,
		arg.ProductSnapshot,
		arg.TotalAmount,
		arg.PrepaymentAmount,
		arg.NetReceivable,
		arg.QuoteID,
		arg.QuoteSnapshot,
		arg.OrganizationID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
